[MenuItem("Tools/Out Scene Transfer/Verify Surface Grass And Flower Preview")]
public static void Verify(){var scene=Main();var root=scene.GetRootGameObjects().First(g=>g.name=="grass");var b=new StringBuilder();int errors=0;foreach(var shader in root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m).Select(m=>m.shader).Distinct())foreach(var m in ShaderUtil.GetShaderMessages(shader).Where(m=>m.severity.ToString()=="Error")){errors++;b.AppendLine(m.message);}b.AppendLine("shaderErrors="+errors+" flowerHeads="+root.GetComponentsInChildren<MeshFilter>(true).Count(f=>f.name.StartsWith("Daisy_"))+" mossSurfaceGroups="+root.GetComponentsInChildren<SurfaceGrassBinding>(true).Length);if(errors>0)throw new Exception(b.ToString());AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);Capture(View(scene),"Out_surface_moss_grass_visible_flowers.png");Selection.activeGameObject=root;File.WriteAllText(W+"out_surface_grass_flowers_verified.txt",b.ToString());}
[MenuItem("Tools/Out Scene Transfer/Refine Visible Flower Head Proportions")]
public static void RefineFlowers(){var scene=Main();var camera=View(scene);var source=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/ArtStyleTest/OutAssets/Codex_PainterlyMeadow/Flowers/Small_Meadow_Daisy.asset");var head=new Vector3(Mathf.Sin(.94f*2.2f)*.022f,.94f,.94f*.94f*.018f);var report=new StringBuilder();foreach(var f in scene.GetRootGameObjects().First(g=>g.name=="grass").GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name.StartsWith("Daisy_"))){var vertices=source.vertices;var normals=source.normals;float depth=camera.WorldToViewportPoint(f.transform.TransformPoint(head)).z;float diameter=Mathf.Clamp(18*2*Mathf.Tan(camera.fieldOfView*Mathf.Deg2Rad*.5f)*depth/900,.18f,.36f);float scale=diameter/.096f;var toward=(camera.transform.position-f.transform.TransformPoint(head)).normalized;var headRotation=Quaternion.FromToRotation(new Vector3(.12f,.94f,-.32f).normalized,Vector3.Lerp(Vector3.up,toward,.72f).normalized);for(int i=33;i<vertices.Length;i++){vertices[i]=head+f.transform.InverseTransformVector(headRotation*((vertices[i]-head)*scale));normals[i]=f.transform.localToWorldMatrix.transpose.MultiplyVector(headRotation*normals[i]).normalized;}var mesh=f.sharedMesh;Undo.RecordObject(mesh,"Make flower heads wider and readable");mesh.vertices=vertices;mesh.normals=normals;mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);report.AppendLine(f.name+" headDiameter="+diameter.ToString("F3"));}AssetDatabase.SaveAssets();File.WriteAllText(W+"out_flower_proportions_result.txt",report.ToString());Verify();}
static Scene Main(){var s=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");if(!s.isLoaded||EditorApplication.isPlaying)throw new Exception("Open out in Edit mode");return s;}
static Camera View(Scene s){return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");}
static string Path(Transform t){return t.parent?Path(t.parent)+"/"+t.name:t.name;}
static void Capture(Camera c,string n){typeof(OutReferenceComposition).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{c,O+n});}
sealed class Builder {public readonly List<Vector3> vertices=new List<Vector3>(),normals=new List<Vector3>();public readonly List<Color> colours=new List<Color>();public readonly List<Vector4> uv=new List<Vector4>();public readonly List<int> triangles=new List<int>();public readonly Matrix4x4 inverse;public readonly Quaternion normalRotation;public Builder(Transform target){inverse=target.worldToLocalMatrix;normalRotation=Quaternion.Inverse(target.rotation);}
 public void Tri(Vector3 a,Vector3 b,Vector3 c,Vector3 na,Vector3 nb,Vector3 nc,Color ca,Color cb,Color cc,Vector4 root){int start=vertices.Count;vertices.Add(inverse.MultiplyPoint3x4(a));vertices.Add(inverse.MultiplyPoint3x4(b));vertices.Add(inverse.MultiplyPoint3x4(c));normals.Add(normalRotation*na);normals.Add(normalRotation*nb);normals.Add(normalRotation*nc);colours.Add(ca);colours.Add(cb);colours.Add(cc);for(int k=0;k<3;k++){uv.Add(root);triangles.Add(start+k);}}
 public Mesh Finish(string name){var mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.SetVertices(vertices);mesh.SetNormals(normals);mesh.SetColors(colours);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();return mesh;}}
sealed class Growth {public Transform target;public Builder moss,tufts;public float noiseScale,step;public bool dome;public System.Random random;public int clusters;public Growth(Transform t,bool building,int seed){target=t;dome=building;moss=new Builder(t);tufts=new Builder(t);random=new System.Random(seed);var rs=t.GetComponentsInChildren<MeshRenderer>(false).Where(r=>r.enabled).ToArray();var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);noiseScale=building?.85f:Mathf.Clamp(2.3f/Mathf.Max(.5f,bounds.size.magnitude),1.1f,4.2f);step=building?.21f:.12f;}
 public float Mask(Vector3 p,Vector3 normal){float noise=Mathf.PerlinNoise(p.x*noiseScale+21,p.z*noiseScale+53)*.65f+Mathf.PerlinNoise(p.z*noiseScale*1.7f+19,p.y*noiseScale*1.7f+7)*.35f;float up=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.12f,.88f,normal.y));float threshold=Mathf.Lerp(.68f,dome?.43f:.34f,up);return Mathf.Clamp01(.5f+(noise-threshold)*3.5f);}
 public void Triangle(Vector3 a,Vector3 b,Vector3 c,Vector3 na,Vector3 nb,Vector3 nc,int depth){if(Mathf.Max(na.y,Mathf.Max(nb.y,nc.y))<.12f)return;float length=Mathf.Max((a-b).magnitude,Mathf.Max((a-c).magnitude,(b-c).magnitude));if(length>step&&depth<6){var ab=(a+b)*.5f;var ac=(a+c)*.5f;var bc=(b+c)*.5f;var nab=(na+nb).normalized;var nac=(na+nc).normalized;var nbc=(nb+nc).normalized;Triangle(a,ab,ac,na,nab,nac,depth+1);Triangle(ab,b,bc,nab,nb,nbc,depth+1);Triangle(ac,bc,c,nac,nbc,nc,depth+1);Triangle(ab,bc,ac,nab,nbc,nac,depth+1);return;}
 float ma=Mask(a,na),mb=Mask(b,nb),mc=Mask(c,nc);if(Mathf.Max(ma,Mathf.Max(mb,mc))<.5f)return;Func<Vector3,float,Color> colour=(p,m)=>new Color(Mathf.PerlinNoise(p.x*4.1f+13,p.z*4.1f+17),1,1,m);moss.Tri(a+na*(.009f+ma*.013f),b+nb*(.009f+mb*.013f),c+nc*(.009f+mc*.013f),na,nb,nc,colour(a,ma),colour(b,mb),colour(c,mc),Vector4.zero);
 float area=Vector3.Cross(b-a,c-a).magnitude*.5f;float expected=area*(dome?32:39);int count=(int)expected+(random.NextDouble()<expected-(int)expected?1:0);for(int k=0;k<count;k++){float u=(float)random.NextDouble(),v=(float)random.NextDouble();if(u+v>1){u=1-u;v=1-v;}var p=a+(b-a)*u+(c-a)*v;var n=(na*(1-u-v)+nb*u+nc*v).normalized;if(n.y<.30f||Mask(p,n)<.65f)continue;p+=n*.024f;float height=.085f+(float)random.NextDouble()*(dome?.13f:.10f);var localRoot=moss.inverse.MultiplyPoint3x4(p);var uv=new Vector4(localRoot.x,localRoot.y,localRoot.z,height);var up=Vector3.Lerp(Vector3.up,n,.16f).normalized;for(int blade=0;blade<3;blade++){float angle=(float)random.NextDouble()*6.283185f;var side=new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle))*(.024f+(float)random.NextDouble()*.018f);var bend=new Vector3(side.z,0,-side.x)*.50f;tufts.Tri(p-side,p+side,p+up*height+bend,n,n,n,Color.white,Color.white,Color.white,uv);}clusters++;}}
 public void Add(MeshRenderer renderer){var filter=renderer.GetComponent<MeshFilter>();var mesh=filter.sharedMesh;var vertices=mesh.vertices;var ns=mesh.normals;var indices=mesh.triangles;var matrix=filter.transform.localToWorldMatrix;var normalMatrix=matrix.inverse.transpose;for(int i=0;i<indices.Length;i+=3){int ia=indices[i],ib=indices[i+1],ic=indices[i+2];var a=matrix.MultiplyPoint3x4(vertices[ia]);var b=matrix.MultiplyPoint3x4(vertices[ib]);var c=matrix.MultiplyPoint3x4(vertices[ic]);var face=Vector3.Cross(b-a,c-a).normalized;var na=ns.Length==vertices.Length?normalMatrix.MultiplyVector(ns[ia]).normalized:face;var nb=ns.Length==vertices.Length?normalMatrix.MultiplyVector(ns[ib]).normalized:face;var nc=ns.Length==vertices.Length?normalMatrix.MultiplyVector(ns[ic]).normalized:face;Triangle(a,b,c,na,nb,nc,0);}}}
static void Export(Growth growth,Transform parent,Material mossMaterial,Material grassMaterial,int index,StringBuilder report){if(growth.moss.vertices.Count==0)return;var g=new GameObject(growth.target.name+" - 苔藓与短草");g.transform.SetParent(parent,false);var binding=g.AddComponent<SurfaceGrassBinding>();binding.surface=growth.target;binding.Apply();string stem=index.ToString("D3")+"_";foreach(var item in new[]{new{builder=growth.moss,name="Moss",material=mossMaterial},new{builder=growth.tufts,name="Short_Grass",material=grassMaterial}}){if(item.builder.vertices.Count==0)continue;var mesh=item.builder.Finish(stem+item.name);AssetDatabase.CreateAsset(mesh,Folder+"/Meshes/"+stem+item.name+".asset");var child=new GameObject(item.name,typeof(MeshFilter),typeof(MeshRenderer));child.transform.SetParent(g.transform,false);child.GetComponent<MeshFilter>().sharedMesh=mesh;var renderer=child.GetComponent<MeshRenderer>();renderer.sharedMaterial=item.material;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.allowOcclusionWhenDynamic=false;}report.AppendLine("surface="+Path(growth.target)+" mossTriangles="+growth.moss.triangles.Count/3+" shortGrassClusters="+growth.clusters);}
static bool Rock(MeshRenderer r){var n=r.name.ToLowerInvariant();if(Path(r.transform).Contains("Lost city"))return false;var mesh=r.GetComponent<MeshFilter>()?.sharedMesh;if(!mesh)return false;return mesh.name.Contains("Angular_Weathered_Rock")||mesh.name.Contains("Chamfered_Stone_Module")||n.Contains("standing stone")||n.Contains("slab")||n.Contains("rubble")||r.transform.root.name=="Foreground - Chipped Stone Groups";}
static int EnlargeFlowers(GameObject[] roots,Transform parent,Camera camera,StringBuilder report){var root=roots.FirstOrDefault(g=>g.name=="Meadow Sparse Flowers");if(!root)return 0;Undo.SetTransformParent(root.transform,parent,"Group flowers under grass");int count=0;var head=new Vector3(Mathf.Sin(.94f*2.2f)*.022f,.94f,.94f*.94f*.018f);foreach(var renderer in root.GetComponentsInChildren<MeshRenderer>(true)){if(!renderer.name.StartsWith("Daisy_"))continue;var filter=renderer.GetComponent<MeshFilter>();var mesh=UnityEngine.Object.Instantiate(filter.sharedMesh);mesh.name=renderer.name+" visible flower head";var vertices=mesh.vertices;float radius=0;for(int i=0;i<vertices.Length;i++)if(vertices[i].y>.88f)radius=Mathf.Max(radius,renderer.transform.TransformVector(vertices[i]-head).magnitude);var projected=camera.WorldToViewportPoint(renderer.transform.TransformPoint(head));float desiredDiameter=Mathf.Clamp(14*2*Mathf.Tan(camera.fieldOfView*Mathf.Deg2Rad*.5f)*projected.z/900,.135f,.30f);float scale=Mathf.Clamp(desiredDiameter/Mathf.Max(.001f,radius*2),2.2f,8f);for(int i=0;i<vertices.Length;i++)if(vertices[i].y>.88f)vertices[i]=head+(vertices[i]-head)*scale;mesh.vertices=vertices;mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Folder+"/Flowers/"+renderer.name+"_Visible.asset");Undo.RecordObject(filter,"Enlarge flower head only");filter.sharedMesh=mesh;EditorUtility.SetDirty(filter);count++;report.AppendLine("flower="+renderer.name+" headScale="+scale.ToString("F2")+" desiredDiameter="+desiredDiameter.ToString("F3"));}return count;}
[MenuItem("Tools/Out Scene Transfer/Add Surface Moss Grass And Enlarge Flowers")]
public static void Apply(){var b=new StringBuilder();try{if(!File.ReadAllText(W+"out_surface_grass_flowers_inspect.txt").Contains("backedUp=True"))throw new Exception("Backup first");var scene=Main();var roots=scene.GetRootGameObjects();var camera=View(scene);var states=roots.SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToDictionary(t=>t,t=>t.localToWorldMatrix);var visibility=roots.SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToDictionary(r=>r,r=>r.enabled);string cameraJson=EditorJsonUtility.ToJson(camera);var lights=roots.SelectMany(g=>g.GetComponentsInChildren<Light>(true)).ToDictionary(l=>l,l=>EditorJsonUtility.ToJson(l));foreach(var dir in new[]{"Meshes","Materials","Flowers"})Directory.CreateDirectory(Folder+"/"+dir);AssetDatabase.Refresh();var root=roots.FirstOrDefault(g=>g.name=="grass");if(!root){root=new GameObject("grass");SceneManager.MoveGameObjectToScene(root,scene);Undo.RegisterCreatedObjectUndo(root,"Add grass group");}if(root.transform.Find("Surface Moss and Grass"))throw new Exception("Surface growth exists");var growthRoot=new GameObject("Surface Moss and Grass");growthRoot.transform.SetParent(root.transform,false);Undo.RegisterCreatedObjectUndo(growthRoot,"Add surface moss and grass");var mossMaterial=new Material(Shader.Find("Codex/Meadow/SurfaceMoss")){name="Grass coloured surface moss"};AssetDatabase.CreateAsset(mossMaterial,Folder+"/Materials/Surface_Moss.mat");var grassMaterial=new Material(Shader.Find("Codex/PainterlyMeadow/DistantHillGrass")){name="Short moss grass - same meadow palette"};AssetDatabase.CreateAsset(grassMaterial,Folder+"/Materials/Surface_Short_Grass.mat");int surface=0,clusters=0;var domes=roots.Where(g=>g.activeInHierarchy&&(g.name.Contains("Mossy_Dome")||g.name=="house")).ToArray();foreach(var dome in domes){var growth=new Growth(dome.transform,true,14320+surface);foreach(var r in dome.GetComponentsInChildren<MeshRenderer>(false).Where(r=>r.enabled&&r.GetComponent<MeshFilter>()?.sharedMesh&&r.sharedMaterials.Any(m=>m&&(m.name.StartsWith("Limestone")||r.name.StartsWith("ShellPanel")||r.name.StartsWith("Course ")))))growth.Add(r);Export(growth,growthRoot.transform,mossMaterial,grassMaterial,surface++,b);clusters+=growth.clusters;}
var stones=roots.SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(false)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponent<MeshFilter>()?.sharedMesh&&Rock(r)&&!domes.Any(d=>r.transform.IsChildOf(d.transform))&&r.bounds.size.magnitude>.40f&&Vector3.Distance(r.bounds.center,camera.transform.position)<65).ToArray();foreach(var stone in stones){var growth=new Growth(stone.transform,false,14320+surface);growth.Add(stone);Export(growth,growthRoot.transform,mossMaterial,grassMaterial,surface++,b);clusters+=growth.clusters;}
int flowers=EnlargeFlowers(roots,root.transform,camera,b);foreach(var item in states){var after=item.Key.localToWorldMatrix;for(int i=0;i<16;i++)if(Mathf.Abs(item.Value[i]-after[i])>.002f)throw new Exception("Original object moved: "+item.Key.name);}foreach(var item in visibility)if(item.Key.enabled!=item.Value)throw new Exception("Original visibility changed");foreach(var light in lights)if(EditorJsonUtility.ToJson(light.Key)!=light.Value)throw new Exception("Light changed");if(EditorJsonUtility.ToJson(camera)!=cameraJson)throw new Exception("Camera changed");int errors=0;foreach(var shader in new[]{mossMaterial.shader,grassMaterial.shader})foreach(var m in ShaderUtil.GetShaderMessages(shader).Where(m=>m.severity.ToString()=="Error")){errors++;b.AppendLine(m.message);}if(errors>0)throw new Exception("Shader errors");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);SceneView.RepaintAll();Capture(camera,"Out_surface_moss_grass_visible_flowers.png");Selection.activeGameObject=root;EditorGUIUtility.PingObject(root);b.AppendLine("surfaces="+surface+" shortGrassClusters="+clusters+" enlargedFlowerHeads="+flowers+" shaderErrors="+errors+" cameraLightsOriginalTransformsAndVisibilityUnchanged=True sceneGroup=grass assetFolder="+Folder+" saved=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_surface_grass_flowers_result.txt",b.ToString());}
[MenuItem("Tools/Out Scene Transfer/Inspect Surface Grass And Flower Heads")]
public static void Inspect(){var b=new StringBuilder();try{var s=Main();var roots=s.GetRootGameObjects();var camera=View(s);string backup="Assets/ArtStyleTest/Scenes_BACKUP/out_before_surface_grass_flowers_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity";if(!EditorSceneManager.SaveScene(s,backup,true))throw new Exception("Backup failed");b.AppendLine("backup="+backup);b.AppendLine("camera="+camera.transform.position+" rot="+camera.transform.eulerAngles+" fov="+camera.fieldOfView);foreach(var root in roots.Where(g=>g.name.Contains("Mossy")||g.name=="house"||g.name=="grass"||g.name.Contains("Flowers"))){var rs=root.GetComponentsInChildren<MeshRenderer>(true);b.AppendLine("root="+root.name+" active="+root.activeInHierarchy+" transform="+root.transform.position+" scale="+root.transform.lossyScale+" renderers="+rs.Length);foreach(Transform t in root.transform)b.AppendLine("child="+t.name+" active="+t.gameObject.activeInHierarchy+" meshes="+t.GetComponentsInChildren<MeshRenderer>(true).Length);}
var flowers=roots.SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(false)).Where(r=>r.name.StartsWith("Daisy_")).ToArray();foreach(var f in flowers.Take(14)){var p=f.transform.TransformPoint(new Vector3(Mathf.Sin(.94f*2.2f)*.022f,.94f,.94f*.94f*.018f));b.AppendLine("flower="+Path(f.transform)+" scale="+f.transform.lossyScale+" headScreen="+camera.WorldToViewportPoint(p)+" bounds="+f.bounds+" mesh="+AssetDatabase.GetAssetPath(f.GetComponent<MeshFilter>().sharedMesh));}b.AppendLine("flowerCount="+flowers.Length);foreach(var r in roots.SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(false)).Where(r=>r.enabled&&(r.name.Contains("slab")||r.name.Contains("Rubble_")||r.name.Contains("fragment")||r.name=="Broken standing stone")).Take(16))b.AppendLine("stone="+Path(r.transform)+" bounds="+r.bounds);Capture(camera,"Out_surface_grass_flowers_before.png");b.AppendLine("backedUp=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_surface_grass_flowers_inspect.txt",b.ToString());}
